(gen_random_uuid(), 'humanas', 'Ciências Humanas e suas Tecnologias', 'História, geografia, filosofia, sociologia e a vida em sociedade.', '#b55d3f', 'globe', 2),
(gen_random_uuid(), 'natureza', 'Ciências da Natureza e suas Tecnologias', 'Biologia, física e química: vida, matéria, energia e ambiente.', '#3f6f8f', 'flask', 3),
(gen_random_uuid(), 'matematica', 'Matemática e suas Tecnologias', 'Números, álgebra, geometria, estatística e modelagem.', '#8a6a2f', 'sigma', 4);
INSERT INTO subjects (id, area_id, code, name, description, sort_order) VALUES
(gen_random_uuid(), (SELECT id FROM areas WHERE code = 'linguagens'), 'portugues', 'Língua Portuguesa e Literatura', 'Interpretação, gêneros, gramática aplicada, literatura e linguagem.', 1),
(gen_random_uuid(), (SELECT id FROM areas WHERE code = 'linguagens'), 'ingles', 'Inglês', 'Compreensão de textos e usos sociais da língua inglesa.', 2),
(gen_random_uuid(), (SELECT id FROM areas WHERE code = 'linguagens'), 'espanhol', 'Espanhol', 'Compreensão de textos e usos sociais da língua espanhola.', 3),
(gen_random_uuid(), (SELECT id FROM areas WHERE code = 'linguagens'), 'artes', 'Artes', 'Linguagens artísticas, patrimônio e diversidade cultural.', 4),
(gen_random_uuid(), (SELECT id FROM areas WHERE code = 'linguagens'), 'educacao-fisica', 'Educação Física', 'Linguagem corporal, movimento, saúde e práticas corporais.', 5),
(gen_random_uuid(), (SELECT id FROM areas WHERE code = 'humanas'), 'historia', 'História', 'Brasil e mundo: processos sociais, políticos, econômicos e culturais.', 1),
(gen_random_uuid(), (SELECT id FROM areas WHERE code = 'humanas'), 'geografia', 'Geografia', 'Território, natureza, população, economia e geopolítica.', 2),
(gen_random_uuid(), (SELECT id FROM areas WHERE code = 'humanas'), 'filosofia', 'Filosofia', 'Ética, política, conhecimento e história da filosofia.', 3),
(gen_random_uuid(), (SELECT id FROM areas WHERE code = 'humanas'), 'sociologia', 'Sociologia', 'Cultura, trabalho, desigualdade, poder e transformações sociais.', 4),
(gen_random_uuid(), (SELECT id FROM areas WHERE code = 'natureza'), 'biologia', 'Biologia', 'Célula, genética, evolução, ecologia, fisiologia e saúde.', 1),
(gen_random_uuid(), (SELECT id FROM areas WHERE code = 'natureza'), 'fisica', 'Física', 'Movimento, energia, termologia, ondas, óptica e eletromagnetismo.', 2),
(gen_random_uuid(), (SELECT id FROM areas WHERE code = 'natureza'), 'quimica', 'Química', 'Matéria, ligações, reações, estequiometria, equilíbrio e orgânica.', 3),
(gen_random_uuid(), (SELECT id FROM areas WHERE code = 'matematica'), 'matematica', 'Matemática', 'Números, funções, geometria, estatística e probabilidade.', 1);
INSERT INTO concepts (id, subject_id, code, name, summary, explanation, difficulty, sort_order) VALUES
(gen_random_uuid(), (SELECT id FROM subjects WHERE code = 'matematica'), 'mat.funcao-afim', 'Função afim', 'Relação entre duas grandezas que varia a uma taxa constante.', $$A função afim tem a forma f(x) = ax + b, com a diferente de zero. O coeficiente a é a taxa de variação: indica quanto f(x) muda quando x aumenta uma unidade. O coeficiente b é o valor inicial, isto é, f(0). O gráfico é uma reta. Esse modelo aparece em tarifas, salários, custos e conversões de unidades.$$, 'medio', 1),
(gen_random_uuid(), (SELECT id FROM subjects WHERE code = 'matematica'), 'mat.funcao-quadratica', 'Função quadrática', 'Função de segundo grau, com parábola, raízes e vértice.', $$A função quadrática tem a forma f(x) = ax² + bx + c, com a diferente de zero. O gráfico é uma parábola. As raízes são os valores de x para os quais f(x) = 0. O vértice representa o ponto de máximo ou de mínimo, com coordenada x igual a -b/(2a). O sinal de a indica a concavidade.$$, 'medio', 2),
(gen_random_uuid(), (SELECT id FROM subjects WHERE code = 'matematica'), 'mat.porcentagem-juros', 'Porcentagem e juros', 'Aplicações de proporcionalidade em descontos, aumentos e juros.', $$Porcentagem é uma razão de base 100. Para calcular p% de um valor, multiplica-se o valor por p/100. Em juros simples, o rendimento incide sempre sobre o capital inicial: J = C · i · t. O montante é M = C + J. Em juros compostos, a taxa incide sobre o montante acumulado.$$, 'facil', 3),
(gen_random_uuid(), (SELECT id FROM subjects WHERE code = 'biologia'), 'bio.celula', 'Estrutura celular', 'Organização básica da célula e função das principais organelas.', $$A célula é a unidade básica da vida. Células procariontes não possuem núcleo delimitado por membrana; eucariontes possuem núcleo e organelas membranosas. A mitocôndria produz a maior parte do ATP na respiração celular, os ribossomos realizam a síntese de proteínas e o complexo de Golgi participa da secreção e da modificação de proteínas.$$, 'facil', 1),
(gen_random_uuid(), (SELECT id FROM subjects WHERE code = 'biologia'), 'bio.mitose-meiose', 'Mitose e meiose', 'Divisão celular: manutenção do número de cromossomos e formação de gametas.', $$A mitose produz duas células geneticamente iguais à célula-mãe e mantém o número de cromossomos. A meiose produz quatro células com metade do número de cromossomos e é responsável pela formação de gametas. O crossing-over, que troca segmentos entre cromátides homólogas, ocorre na prófase I da meiose e aumenta a variabilidade genética.$$, 'medio', 2),
(gen_random_uuid(), (SELECT id FROM subjects WHERE code = 'fisica'), 'fis.leis-newton', 'Leis de Newton', 'Relação entre força, massa e aceleração.', $$A primeira lei de Newton trata da inércia: sem força resultante, um corpo permanece em repouso ou em movimento retilíneo uniforme. A segunda lei relaciona força resultante, massa e aceleração: F = m · a. A terceira lei afirma que toda ação corresponde a uma reação de mesma intensidade e direção, em sentido oposto.$$, 'medio', 1),
(gen_random_uuid(), (SELECT id FROM subjects WHERE code = 'quimica'), 'qui.ligacoes', 'Ligações químicas', 'Interações que mantêm átomos unidos em substâncias.', $$Ligações iônicas envolvem transferência de elétrons e atração entre íons, como no NaCl. Ligações covalentes envolvem compartilhamento de elétrons, como na molécula de água. Ligações metálicas envolvem elétrons livres em uma rede de cátions. As propriedades das substâncias dependem do tipo de ligação e das interações intermoleculares.$$, 'medio', 1),
(gen_random_uuid(), (SELECT id FROM subjects WHERE code = 'portugues'), 'por.funcoes-linguagem', 'Funções da linguagem', 'Usos da linguagem orientados ao referente, ao emissor, ao receptor, ao código, ao canal ou à mensagem.', $$As funções da linguagem indicam o foco comunicativo. A referencial informa sobre a realidade; a emotiva expressa o emissor; a conativa busca influenciar o receptor; a metalinguística fala sobre a própria linguagem; a fática testa ou mantém o canal; a poética valoriza a forma da mensagem. Em um texto, normalmente há mais de uma função, com uma predominante.$$, 'facil', 1),
(gen_random_uuid(), (SELECT id FROM subjects WHERE code = 'ingles'), 'ing.reading', 'Reading comprehension', 'Estratégias de leitura e compreensão de textos em inglês.', $$Leia o texto em blocos, observe o título, as palavras cognatas e os conectivos. Palavras como however, although e therefore indicam contraste ou consequência. Não é necessário traduzir cada palavra: identifique a ideia central, o propósito e a relação entre as frases.$$, 'facil', 1),
(gen_random_uuid(), (SELECT id FROM subjects WHERE code = 'espanhol'), 'esp.lectura', 'Comprensión lectora', 'Estrategias de lectura y comprensión de textos en español.', $$Observa las palabras cognatas, los conectores y el contexto. Términos como sin embargo, aunque y por lo tanto indican contraste o consecuencia. La comprensión global importa más que la traducción literal de cada palabra.$$, 'facil', 1),
(gen_random_uuid(), (SELECT id FROM subjects WHERE code = 'historia'), 'his.primeira-republica', 'Primeira República', 'Política, sociedade e conflitos no Brasil entre 1889 e 1930.', $$A Primeira República foi marcada pela política dos governadores, pelo coronelismo e pelo domínio das oligarquias estaduais. O voto era restrito e frequentemente controlado por chefes locais. Movimentos como a Revolta da Vacina (1904) expressaram tensões entre as reformas urbanas, a saúde pública e a população pobre.$$, 'medio', 1),
(gen_random_uuid(), (SELECT id FROM subjects WHERE code = 'geografia'), 'geo.urbanizacao', 'Urbanização brasileira', 'Crescimento das cidades, metropolização e desigualdades urbanas.', $$A urbanização brasileira acelerou-se a partir da segunda metade do século XX, com migração campo-cidade e industrialização. A metropolização consolidou grandes aglomerados urbanos e a conurbação entre municípios. O crescimento rápido sem planejamento suficiente produziu déficit habitacional, ocupações irregulares e favelização.$$, 'medio', 1),
(gen_random_uuid(), (SELECT id FROM subjects WHERE code = 'filosofia'), 'fil.etica', 'Ética', 'Reflexão sobre normas, valores e critérios da ação moral.', $$A ética investiga como devemos agir. Kant propôs o imperativo categórico: agir segundo uma máxima que possa ser universalizada. O utilitarismo avalia a ação pelas consequências, buscando a maior felicidade para o maior número de pessoas. A ética das virtudes, associada a Aristóteles, concentra-se no caráter e nas virtudes.$$, 'medio', 1),
(gen_random_uuid(), (SELECT id FROM subjects WHERE code = 'sociologia'), 'soc.cultura', 'Cultura e sociedade', 'Cultura, identidade, etnocentrismo e relativismo cultural.', $$Cultura é o conjunto de práticas, valores, símbolos e formas de organização de um grupo. O etnocentrismo julga outras culturas pelos padrões da própria cultura. O relativismo cultural propõe compreender cada cultura em seu contexto, sem hierarquias automáticas. O debate não elimina a possibilidade de crítica: exige cuidado com generalizações e com a diversidade interna de cada grupo.$$, 'medio', 1);
INSERT INTO questions (id, concept_id, code, statement, option_a, option_b, option_c, option_d, option_e, correct_option, explanation, difficulty, source, license) VALUES
(gen_random_uuid(), (SELECT id FROM concepts WHERE code = 'mat.funcao-afim'), 'MAT-FAFIM-001', $$Uma empresa de fretes cobra uma taxa fixa de R$ 50,00 mais R$ 8,00 por quilômetro rodado. Qual é o valor cobrado por um frete de 12 km?$$, $$R$ 96,00$$, $$R$ 106,00$$, $$R$ 146,00$$, $$R$ 156,00$$, $$R$ 196,00$$, 'C', $$O custo é dado por C(x) = 50 + 8x. Para x = 12, C(12) = 50 + 96 = 146. Portanto, o frete custa R$ 146,00.$$, 'facil', 'Autoral — Projeto ENEM', 'CC BY-SA 4.0'),
(gen_random_uuid(), (SELECT id FROM concepts WHERE code = 'mat.funcao-afim'), 'MAT-FAFIM-002', $$Considere a função f(x) = 3x - 6. Qual é o valor de f(5)?$$, $$6$$, $$9$$, $$12$$, $$15$$, $$21$$, 'B', $$Substituindo x por 5: f(5) = 3 · 5 - 6 = 15 - 6 = 9.$$, 'facil', 'Autoral — Projeto ENEM', 'CC BY-SA 4.0'),
(gen_random_uuid(), (SELECT id FROM concepts WHERE code = 'mat.funcao-quadratica'), 'MAT-FQUAD-001', $$Quais são as raízes da equação x² - 5x + 6 = 0?$$, $$1 e 6$$, $$2 e 3$$, $$-2 e -3$$, $$0 e 6$$, $$3 e 5$$, 'B', $$A equação pode ser fatorada como (x - 2)(x - 3) = 0. Portanto, as raízes são x = 2 e x = 3.$$, 'facil', 'Autoral — Projeto ENEM', 'CC BY-SA 4.0'),
(gen_random_uuid(), (SELECT id FROM concepts WHERE code = 'mat.funcao-quadratica'), 'MAT-FQUAD-002', $$O vértice da parábola f(x) = x² - 4x + 7 é:$$, $$(2, 3)$$, $$(-2, 3)$$, $$(2, 7)$$, $$(4, 7)$$, $$(0, 7)$$, 'A', $$A coordenada x do vértice é -b/(2a) = -(-4)/(2·1) = 2. Substituindo, f(2) = 4 - 8 + 7 = 3. O vértice é (2, 3).$$, 'medio', 'Autoral — Projeto ENEM', 'CC BY-SA 4.0'),
(gen_random_uuid(), (SELECT id FROM concepts WHERE code = 'mat.porcentagem-juros'), 'MAT-PORC-001', $$Em uma turma de 250 estudantes, 20% participaram de um simulado. Quantos estudantes participaram?$$, $$20$$, $$40$$, $$50$$, $$60$$, $$75$$, 'C', $$20% de 250 é 0,20 · 250 = 50. Portanto, 50 estudantes participaram.$$, 'facil', 'Autoral — Projeto ENEM', 'CC BY-SA 4.0'),
(gen_random_uuid(), (SELECT id FROM concepts WHERE code = 'mat.porcentagem-juros'), 'MAT-PORC-002', $$Um capital de R$ 1.000,00 foi aplicado a juros simples de 2% ao mês durante 5 meses. Qual é o montante?$$, $$R$ 1.020,00$$, $$R$ 1.050,00$$, $$R$ 1.100,00$$, $$R$ 1.200,00$$, $$R$ 1.500,00$$, 'C', $$J = C · i · t = 1000 · 0,02 · 5 = 100. O montante é M = C + J = 1000 + 100 = 1100.$$, 'facil', 'Autoral — Projeto ENEM', 'CC BY-SA 4.0'),
(gen_random_uuid(), (SELECT id FROM concepts WHERE code = 'bio.celula'), 'BIO-CEL-001', $$Qual organela é responsável pela maior parte da produção de ATP na respiração celular?$$, $$Ribossomo$$, $$Mitocôndria$$, $$Lisossomo$$, $$Complexo de Golgi$$, $$Núcleo$$, 'B', $$A mitocôndria é a principal organela envolvida na respiração celular aeróbia e na produção de ATP. Os ribossomos sintetizam proteínas; os lisossomos participam da digestão intracelular.$$, 'facil', 'Autoral — Projeto ENEM', 'CC BY-SA 4.0'),
(gen_random_uuid(), (SELECT id FROM concepts WHERE code = 'bio.celula'), 'BIO-CEL-002', $$A principal diferença entre células procariontes e eucariontes é que as procariontes:$$, $$possuem núcleo organizado$$, $$não possuem material genético$$, $$não possuem núcleo delimitado por membrana$$, $$possuem cloroplastos em todas as espécies$$, $$não possuem ribossomos$$, 'C', $$Células procariontes não têm núcleo delimitado por membrana; o material genético fica no citoplasma. Células eucariontes possuem núcleo e organelas membranosas.$$, 'facil', 'Autoral — Projeto ENEM', 'CC BY-SA 4.0'),
(gen_random_uuid(), (SELECT id FROM concepts WHERE code = 'bio.mitose-meiose'), 'BIO-MEI-001', $$O processo de divisão celular que origina gametas com metade do número de cromossomos da célula-mãe é a:$$, $$mitose$$, $$meiose$$, $$fotossíntese$$, $$respiração celular$$, $$tradução$$, 'B', $$A meiose reduz o número de cromossomos pela metade e forma gametas. A mitose mantém o número de cromossomos e produz células geneticamente iguais.$$, 'facil', 'Autoral — Projeto ENEM', 'CC BY-SA 4.0'),
(gen_random_uuid(), (SELECT id FROM concepts WHERE code = 'bio.mitose-meiose'), 'BIO-MEI-002', $$O crossing-over, fenômeno que aumenta a variabilidade genética, ocorre principalmente na:$$, $$metáfase II$$, $$prófase I$$, $$anáfase II$$, $$telófase$$, $$mitose$$, 'B', $$O crossing-over ocorre na prófase I da meiose, quando cromátides homólogas trocam segmentos. Isso contribui para a variabilidade genética dos gametas.$$, 'medio', 'Autoral — Projeto ENEM', 'CC BY-SA 4.0'),
(gen_random_uuid(), (SELECT id FROM concepts WHERE code = 'fis.leis-newton'), 'FIS-NEW-001', $$A lei que afirma que um corpo permanece em repouso ou em movimento retilíneo uniforme quando a resultante das forças é nula é a:$$, $$primeira lei de Newton$$, $$segunda lei de Newton$$, $$terceira lei de Newton$$, $$lei da gravitação universal$$, $$lei de Hooke$$, 'A', $$A primeira lei de Newton, ou lei da inércia, afirma que a ausência de força resultante implica manutenção do estado de repouso ou de movimento retilíneo uniforme.$$, 'facil', 'Autoral — Projeto ENEM', 'CC BY-SA 4.0'),
(gen_random_uuid(), (SELECT id FROM concepts WHERE code = 'fis.leis-newton'), 'FIS-NEW-002', $$Um corpo de massa 2 kg está sujeito a uma aceleração de 5 m/s². Qual é a força resultante?$$, $$5 N$$, $$10 N$$, $$15 N$$, $$20 N$$, $$25 N$$, 'B', $$Pela segunda lei de Newton, F = m · a = 2 · 5 = 10 N.$$, 'facil', 'Autoral — Projeto ENEM', 'CC BY-SA 4.0'),
(gen_random_uuid(), (SELECT id FROM concepts WHERE code = 'qui.ligacoes'), 'QUI-LIG-001', $$A ligação predominante no cloreto de sódio (NaCl) é:$$, $$covalente apolar$$, $$covalente polar$$, $$iônica$$, $$metálica$$, $$ponte de hidrogênio$$, 'C', $$O NaCl é formado por íons Na⁺ e Cl⁻, mantidos por atração eletrostática. Essa é uma ligação iônica.$$, 'facil', 'Autoral — Projeto ENEM', 'CC BY-SA 4.0'),
(gen_random_uuid(), (SELECT id FROM concepts WHERE code = 'qui.ligacoes'), 'QUI-LIG-002', $$A ligação covalente é caracterizada por:$$, $$transferência definitiva de elétrons$$, $$compartilhamento de elétrons$$, $$atração entre íons$$, $$mar de elétrons livres$$, $$forças de Van der Waals$$, 'B', $$Na ligação covalente, os átomos compartilham pares de elétrons. A transferência definitiva caracteriza a ligação iônica; o mar de elétrons caracteriza a ligação metálica.$$, 'facil', 'Autoral — Projeto ENEM', 'CC BY-SA 4.0'),
(gen_random_uuid(), (SELECT id FROM concepts WHERE code = 'por.funcoes-linguagem'), 'POR-FUN-001', $$Na frase “Compre agora! Últimas unidades!”, predomina a função:$$, $$referencial$$, $$emotiva$$, $$conativa$$, $$metalinguística$$, $$poética$$, 'C', $$A função conativa, ou apelativa, busca influenciar o receptor por meio de verbos no imperativo e chamadas diretas. “Compre agora!” é um exemplo típico.$$, 'facil', 'Autoral — Projeto ENEM', 'CC BY-SA 4.0'),
(gen_random_uuid(), (SELECT id FROM concepts WHERE code = 'por.funcoes-linguagem'), 'POR-FUN-002', $$Em um verbete que explica a origem da palavra “literatura”, predomina a função:$$, $$referencial$$, $$fática$$, $$conativa$$, $$metalinguística$$, $$emotiva$$, 'D', $$A função metalinguística ocorre quando a linguagem explica a própria linguagem, como em verbetes, definições e análises do código.$$, 'medio', 'Autoral — Projeto ENEM', 'CC BY-SA 4.0'),
(gen_random_uuid(), (SELECT id FROM concepts WHERE code = 'ing.reading'), 'ING-READ-001', $$Read the text: “Many students believe that studying more hours is always better. However, research suggests that active recall and spaced practice are more effective than passive rereading.” According to the text, which strategy is more effective?$$, $$Passive rereading$$, $$Studying more hours$$, $$Active recall and spaced practice$$, $$Highlighting only$$, $$Sleeping less$$, 'C', $$The text states that active recall and spaced practice are more effective than passive rereading. The word “However” signals a contrast with the belief that more hours are always better.$$, 'facil', 'Autoral — Projeto ENEM', 'CC BY-SA 4.0'),
(gen_random_uuid(), (SELECT id FROM concepts WHERE code = 'ing.reading'), 'ING-READ-002', $$In the text, the word “However” introduces:$$, $$a cause$$, $$a contrast$$, $$an example$$, $$a conclusion$$, $$a definition$$, 'B', $$“However” is a contrast connector. It indicates that the second idea contrasts with the first one.$$, 'facil', 'Autoral — Projeto ENEM', 'CC BY-SA 4.0'),
(gen_random_uuid(), (SELECT id FROM concepts WHERE code = 'esp.lectura'), 'ESP-LEC-001', $$Lee el texto: “El ejercicio físico regular mejora la salud cardiovascular y reduce el estrés.” Según el texto, el ejercicio físico regular:$$, $$empeora el estrés$$, $$mejora la salud cardiovascular$$, $$solo sirve para perder peso$$, $$no tiene efectos sobre la salud$$, $$aumenta el sedentarismo$$, 'B', $$El texto afirma que el ejercicio regular mejora la salud cardiovascular y reduce el estrés.$$, 'facil', 'Autoral — Projeto ENEM', 'CC BY-SA 4.0'),
(gen_random_uuid(), (SELECT id FROM concepts WHERE code = 'esp.lectura'), 'ESP-LEC-002', $$En el texto, la palabra “reduce” significa:$$, $$aumenta$$, $$disminuye$$, $$mantiene$$, $$ignora$$, $$duplica$$, 'B', $$“Reduce” significa disminuir. En el contexto, el ejercicio disminuye el estrés.$$, 'facil', 'Autoral — Projeto ENEM', 'CC BY-SA 4.0'),
(gen_random_uuid(), (SELECT id FROM concepts WHERE code = 'his.primeira-republica'), 'HIS-REP-001', $$A política dos governadores, característica da Primeira República, baseava-se em:$$, $$voto secreto e universal$$, $$alianças entre o governo federal e oligarquias estaduais$$, $$fim do coronelismo$$, $$parlamentarismo$$, $$sufrágio feminino$$, 'B', $$A política dos governadores articulava o governo federal e as oligarquias estaduais, garantindo apoio político em troca de autonomia e recursos. O coronelismo e o controle local do voto foram elementos centrais.$$, 'medio', 'Autoral — Projeto ENEM', 'CC BY-SA 4.0'),
(gen_random_uuid(), (SELECT id FROM concepts WHERE code = 'his.primeira-republica'), 'HIS-REP-002', $$A Revolta da Vacina, ocorrida no Rio de Janeiro em 1904, foi motivada principalmente por:$$, $$a imposição da vacinação obrigatória e a insatisfação com as reformas urbanas$$, $$a luta pela abolição da escravidão$$, $$a Guerra de Canudos$$, $$a Revolta da Chibata$$, $$a Proclamação da República$$, 'A', $$A Revolta da Vacina combinou a oposição à vacinação obrigatória com o descontentamento popular diante das reformas urbanas e das condições de vida no Rio de Janeiro.$$, 'medio', 'Autoral — Projeto ENEM', 'CC BY-SA 4.0'),
(gen_random_uuid(), (SELECT id FROM concepts WHERE code = 'geo.urbanizacao'), 'GEO-URB-001', $$O processo de metropolização caracteriza-se por:$$, $$redução das cidades médias$$, $$crescimento das metrópoles e integração de áreas urbanas$$, $$migração em massa para o campo$$, $$fim da atividade industrial$$, $$diminuição da população urbana$$, 'B', $$Metropolização é o crescimento e a integração de grandes áreas urbanas, frequentemente com conurbação entre municípios. Não se confunde com a simples redução ou aumento de uma cidade isolada.$$, 'medio', 'Autoral — Projeto ENEM', 'CC BY-SA 4.0'),
(gen_random_uuid(), (SELECT id FROM concepts WHERE code = 'geo.urbanizacao'), 'GEO-URB-002', $$A favelização está frequentemente associada a:$$, $$planejamento urbano eficiente$$, $$ocupação irregular e déficit habitacional$$, $$aumento da arborização$$, $$transporte ferroviário$$, $$redução da desigualdade$$, 'B', $$A favelização relaciona-se à falta de moradia acessível, à ocupação irregular de áreas e à desigualdade socioespacial.$$, 'medio', 'Autoral — Projeto ENEM', 'CC BY-SA 4.0'),
(gen_random_uuid(), (SELECT id FROM concepts WHERE code = 'fil.etica'), 'FIL-ETI-001', $$O imperativo categórico, formulado por Kant, propõe que se deve agir:$$, $$apenas conforme as consequências$$, $$segundo uma máxima que possa ser universalizada$$, $$buscando apenas a felicidade pessoal$$, $$conforme os costumes da época$$, $$sem qualquer princípio racional$$, 'B', $$Kant formula o imperativo categórico como um princípio racional: deve-se agir apenas segundo uma máxima que se possa querer como lei universal.$$, 'medio', 'Autoral — Projeto ENEM', 'CC BY-SA 4.0'),
(gen_random_uuid(), (SELECT id FROM concepts WHERE code = 'fil.etica'), 'FIL-ETI-002', $$A corrente ética que avalia a ação pelas suas consequências e pela busca da maior felicidade para o maior número de pessoas é:$$, $$kantismo$$, $$utilitarismo$$, $$ética das virtudes$$, $$estoicismo$$, $$existencialismo$$, 'B', $$O utilitarismo, associado a autores como Bentham e Mill, avalia a ação por suas consequências e pela maximização da felicidade ou do bem-estar geral.$$, 'medio', 'Autoral — Projeto ENEM', 'CC BY-SA 4.0'),
(gen_random_uuid(), (SELECT id FROM concepts WHERE code = 'soc.cultura'), 'SOC-CUL-001', $$O etnocentrismo consiste em:$$, $$compreender outra cultura em seus próprios termos$$, $$julgar outras culturas pelos padrões da própria cultura$$, $$defender a diversidade cultural$$, $$praticar a alteridade$$, $$estudar a cultura sem hierarquias$$, 'B', $$Etnocentrismo é a tendência de avaliar outras culturas a partir dos valores e padrões da própria cultura, frequentemente gerando preconceito.$$, 'facil', 'Autoral — Projeto ENEM', 'CC BY-SA 4.0'),
(gen_random_uuid(), (SELECT id FROM concepts WHERE code = 'soc.cultura'), 'SOC-CUL-002', $$O relativismo cultural defende que:$$, $$uma cultura é superior às outras$$, $$as culturas devem ser compreendidas em seus próprios contextos$$, $$a cultura não influencia o comportamento$$, $$todas as culturas são idênticas$$, $$apenas a cultura ocidental é válida$$, 'B', $$O relativismo cultural propõe compreender práticas e valores culturais dentro de seus contextos, evitando julgamentos automáticos a partir de outra cultura.$$, 'facil', 'Autoral — Projeto ENEM', 'CC BY-SA 4.0');
